import { registerWebComponents } from '@domg-wc/common';
import { VlTextareaRichComponent } from '@domg-wc/components/form';

registerWebComponents([VlTextareaRichComponent]);

// vl-change volgt op elke wijziging van de waarde, door invoer in de editor en door code. Luister niet naar vl-input:
// dat volgt niet op invoer in de editor (zie notes). event.detail.value is de inhoud van de editor als HTML, bv.
// '<p><b>vet</b></p>'.
document.querySelector('#textarea-rich-default').addEventListener('vl-change', (event) => {
    console.log(event.detail.value);
});
